import { useFetchQueueTime } from "@/core/hooks/use-queue-time";
import { PlaceholderImageHelper, TodayHelper, exhaustiveCheck } from "@/core/helpers";
import { useHashState } from "@/core/hooks/use-hash-state";
import { z } from "zod";
import { existingThemes } from "@/core/types/existing-themes";
import { useOpeningHoursForDate } from "@/core/hooks";
import { ClosedDisplay, ParkLogoDisplay, QueueTimeDisplay, RideWillOpenDisplay } from "./display-versions";
import { displayStateAndQueueData } from "@/core/components/modules/queue-display/use-grouped-and-sorted-rides";

/** Settings that can be adjusted through URL hash parameters */
const hashStateSchema = z.object({
  /** Color theme */
  theme: z.enum(existingThemes).optional(),
  /** Size of the ride title (default is `small`). Hidden if `none` */
  titleSize: z.enum(["none", "small", "large"]).optional().default("small"),
});

/**
 * Display to be used on screens by Blocks. \
 * Shows single ride title and queue time or stoppage information.
 * Show park logo if park is closed or ride is open but queue time is missing.
 *
 * @remarks
 * - Settings that can be adjusted through URL hash parameters:
 *    - theme
 *    - titleSize
 */
export const RideQueueDisplay = ({ title, rideId }: { title: string; rideId: number }) => {
  const [{ titleSize, theme }] = useHashState(hashStateSchema);

  const now = TodayHelper.getNow();
  const todaysOpeningHours = useOpeningHoursForDate(now);
  const closedImage = PlaceholderImageHelper.getPlaceholderImage("rideQueueDisplay");
  const queueTimeObject = useFetchQueueTime(rideId, {
    updateInterval: 60_000,
    includeEvents: true,
    includeHideForWeb: true,
  });

  const displayState = displayStateAndQueueData(queueTimeObject, todaysOpeningHours, now);

  const sharedProps = {
    titleSize,
    theme,
    title,
  };

  switch (displayState.state) {
    case "NOT_OPEN_TODAY":
      return <ParkLogoDisplay {...sharedProps} closedImage={closedImage} />;
    case "OPENS_SOON":
      return (
        <RideWillOpenDisplay
          {...sharedProps}
          openingTime={displayState.openingTime}
          closingTime={displayState.closingTime}
        />
      );
    case "QUEUE_TIME":
      // Whene queue time is "-", we should handle it the same as NOT_OPEN_TODAY
      if (displayState.queueData.queueTime === "-") {
        return <ParkLogoDisplay {...sharedProps} closedImage={closedImage} />;
      }
      return (
        <QueueTimeDisplay {...sharedProps} queueData={displayState.queueData} closingTime={displayState.closingTime} />
      );
    case "CLOSED":
      return <ClosedDisplay {...sharedProps} queueData={displayState.queueData} />;
    default:
      return exhaustiveCheck(displayState);
  }
};
