// @ts-strict-ignore
import { isNonEmptyArray } from "@/core/helpers/array-helper";
import LanguageHelper from "@/core/helpers/language-helper";
import { RideBlock } from "@/core/types/ride/ride";

class RideStore {
  rides: any = {};
  initialized = false;

  populateStore(rides: any): void {
    if (!isNonEmptyArray(rides) || this.initialized) {
      return;
    }

    rides.forEach((rides: any) => {
      if (this.rides[rides.node.node_locale] instanceof Array) {
        this.rides[rides.node.node_locale].push(rides.node);
      } else {
        this.rides[rides.node.node_locale] = [rides.node];
      }
    });

    this.initialized = true;
  }

  getRideById(rideId: number, locale = LanguageHelper.getCurrentLocale()): RideBlock {
    const rideItem = isNonEmptyArray(this.rides[locale])
      ? this.rides[locale].find((item) => item.rideId === rideId)
      : null;
    return rideItem;
  }

  getRideByContentfulId(contentfulId: string, locale = LanguageHelper.getCurrentLocale()): RideBlock {
    const rideItem = this.rides[locale]?.find((item) => item.contentful_id === contentfulId) ?? null;
    return rideItem;
  }

  getImageInListForRide(rideId: number, locale = LanguageHelper.getCurrentLocale()): any {
    const rideItem = this.getRideById(rideId, locale);
    return rideItem && rideItem.imageInList ? rideItem.imageInList.file.url : null;
  }
}

const store = new RideStore();
export default store;
