import styles from "./ride-queue-display.module.less";
import { PropsWithChildren } from "react";
import { motion } from "framer-motion";
import { multipleClassNames } from "@/core/helpers";
import AutoSizedText from "@/core/components/primitives/auto-sized-text/auto-sized-text";
import { QueueDisplayRideQueueData } from "@/core/components/modules/queue-display/use-grouped-and-sorted-rides";
import { useTranslation } from "react-i18next";
import { getRideStoppageInfo } from "@/core/helpers/get-ride-stoppage-info";

const fontWeight = "var(--common-font-font-weight-heading-xl)";

export type SharedProps = {
  titleSize: "none" | "small" | "large";
  theme?: string;
  title: string;
};

const Title = ({ title, titleSize }: Required<Pick<SharedProps, "title" | "titleSize">>) => (
  <div className={multipleClassNames(styles.gridForAutoSizedText, styles.title)} data-title-size={titleSize}>
    <AutoSizedText text={title} fontWeight={fontWeight} paddingMode="dynamic" />
  </div>
);

const Wrapper = ({
  theme,
  className,
  children,
}: PropsWithChildren<Pick<SharedProps, "theme">> & {
  className: string;
}) => {
  return (
    <motion.div
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ delay: 0.5 }}
      className={multipleClassNames(
        styles.wrapper,
        styles.gridForAutoSizedText,
        theme && `component-theme component-theme-${theme} ${theme}`,
        className,
      )}
    >
      {children}
    </motion.div>
  );
};

export const ParkLogoDisplay = ({ theme, titleSize, title, closedImage }: SharedProps & { closedImage: string }) => {
  return (
    <Wrapper theme={theme} className={styles.parkLogo}>
      <div className={multipleClassNames(styles.imageWrapper, styles.gridForAutoSizedText)}>
        {closedImage && (
          <img src={closedImage} className={multipleClassNames(styles.closedImage, styles.gridForAutoSizedText)} />
        )}
      </div>

      {titleSize !== "none" && <Title title={title} titleSize={titleSize} />}
    </Wrapper>
  );
};

export const QueueTimeDisplay = ({
  theme,
  titleSize,
  title,
  queueData,
  closingTime,
}: SharedProps & { queueData: QueueDisplayRideQueueData; closingTime: string | null }) => {
  const { t } = useTranslation();

  const expectedWaitTimeLabel = t("rideQueueDisplay.expectedQueueTimeSweEng");
  const closingTimeString = closingTime && `${t("rideQueueDisplay.closingTimeSweEng")} ${closingTime}`;

  return (
    <Wrapper theme={theme} className={styles.queueTime}>
      {titleSize !== "none" && <Title title={title} titleSize={titleSize} />}

      <div className={styles.gridForAutoSizedText}>
        <AutoSizedText
          text={expectedWaitTimeLabel}
          widestText={expectedWaitTimeLabel}
          fontWeight={fontWeight}
          padding="0"
          alignItems="end"
        />
      </div>
      <div className={styles.gridForAutoSizedText}>
        <AutoSizedText
          text={queueData.queueTime}
          fontWeight={fontWeight}
          padding="0"
          lineHeight={0.85}
          alignItems="start"
        />
      </div>

      {closingTimeString && (
        <div className={multipleClassNames(styles.gridForAutoSizedText, styles.closingTime)}>
          <AutoSizedText
            text={closingTimeString}
            widestText={expectedWaitTimeLabel}
            fontWeight={fontWeight}
            padding="0"
          />
        </div>
      )}
    </Wrapper>
  );
};

export const RideWillOpenDisplay = ({
  theme,
  titleSize,
  title,
  openingTime,
  closingTime,
}: SharedProps & { openingTime: string; closingTime: string | null }) => {
  const { t } = useTranslation();

  const openingTimeLabel = t("rideQueueDisplay.openingTimeSweEng");
  const closingTimeString = closingTime && `${t("rideQueueDisplay.closingTimeSweEng")} ${closingTime}`;

  return (
    <Wrapper theme={theme} className={styles.willOpen}>
      {titleSize !== "none" && <Title title={title} titleSize={titleSize} />}

      <div className={styles.gridForAutoSizedText}>
        <AutoSizedText text={openingTimeLabel} alignItems="end" fontWeight={fontWeight} padding="0 17" />
      </div>
      <div className={styles.gridForAutoSizedText}>
        <AutoSizedText text={openingTime} alignItems="start" fontWeight={fontWeight} padding="0 5" lineHeight={0.85} />
      </div>

      {closingTimeString && (
        <div className={multipleClassNames(styles.gridForAutoSizedText, styles.closingTime)}>
          <AutoSizedText text={closingTimeString} fontWeight={fontWeight} padding="0 10" paddingMode="fixedWidth" />
        </div>
      )}
    </Wrapper>
  );
};

export const ClosedDisplay = ({
  theme,
  titleSize,
  title,
  queueData,
}: SharedProps & { queueData: QueueDisplayRideQueueData }) => {
  const { t } = useTranslation();
  const stoppageInfo = getRideStoppageInfo(queueData.queueState, queueData.stoppageStatus, t);

  return (
    <Wrapper theme={theme} className={styles.closed}>
      <div className={multipleClassNames(styles.stoppageInfo, styles.gridForAutoSizedText)}>
        <div className={styles.gridForAutoSizedText}>
          <AutoSizedText text={stoppageInfo.stoppageTextSv} alignItems="flex-end" fontWeight={fontWeight} padding="0" />
        </div>
        <div className={multipleClassNames(styles.english, styles.gridForAutoSizedText)}>
          <AutoSizedText
            text={stoppageInfo.stoppageTextEn}
            fontWeight={fontWeight}
            alignItems="flex-start"
            padding="0"
          />
        </div>
      </div>
      <div className={styles.gridForAutoSizedText}>
        <AutoSizedText
          text=""
          justifyContent="center"
          fontWeight={fontWeight}
          icon={stoppageInfo.stoppageIcon}
          padding="0"
        />
      </div>

      {titleSize !== "none" && <Title title={title} titleSize={titleSize} />}
    </Wrapper>
  );
};
