import { useCallback, useEffect, useMemo, useState } from "react";
import { LocationHelper } from "../helpers";
import { z } from "zod";
import { decode, encode } from "qss";

export type HashParams<T extends string> = Record<T, Array<string>>;

const decodeHashParamFromWindowLocation = () => {
  if (typeof window !== "undefined") {
    const rawHashParamsFromLocation = window.location.hash.substring(1);
    const hash: Record<string, unknown> = decode(rawHashParamsFromLocation);

    // Try to parse any query params that might be json
    for (const key in hash) {
      const value = hash[key];
      if (typeof value === "string") {
        try {
          hash[key] = JSON.parse(value);
        } catch (err) {
          // If it fails, just keep the value as is
        }
      }
    }
    return hash;
  }
  return {};
};

const encodeHashParamAndUpdateWindowLocation = (hash: Record<string, unknown>) => {
  if (typeof window !== "undefined") {
    //need to stringify all values, so that eventual objects are stringified.
    for (const key in hash) {
      const value = hash[key];
      hash[key] = JSON.stringify(value);
    }

    const encodedHashParam = encode(hash);
    window.location.hash = encodedHashParam;
  }
};

/**
 * This is a type utility that will only accept zod schemas where the fields ends with `optional()` or `default(...)`
 */
type SchemaWithOnlyDefaultAndOptional<Schema> = Schema extends z.ZodObject<infer U>
  ? U extends Record<string, z.ZodOptional<any> | z.ZodDefault<any>>
    ? Schema
    : never
  : never;

// Overload signatures
/**
 * @deprecated Use the overload with a zod schema instead
 * Used to keep state in the hash params of the url
 * @param keys The list of keys to keep in the hash. Eg. ["filter", "quickFilter"]
 * @returns An array with the hash params and a function to update them
 */
export function useHashState<T extends string>(
  keys: Array<T>,
): readonly [HashParams<T>, (newParams: Partial<HashParams<T>>) => void];
/**
 * @param schema A zod schema that defines the shape of the hash params.
 * Each field in the schema must end with `optional()` or `default(...)`
 * @returns An array with the hash params and a function to update them
 *
 * @remarks If hash params are used for styling (eg. themes), the DOM doesn't always update correctly when the hash changes. \
 * Include `if (typeof window === "undefined") return null;` before return of component to avoid this. \
 * Example:
 * ```tsx
 *    const MyComponent = () => {
 *    const myComponentHashStateSchema = z.object({
 *       theme: z.enum(existingThemes).optional(),
 *    });
 *    const [hashParams] = useHashState(myComponentHashStateSchema);
 *    const { theme } = hashParams;
 *    if (typeof window === "undefined") return null; // Prevents SSR issues when using hash params for styling
 *    return <div className={theme}>Hello World</div>;
 * }
 * ```
 */
export function useHashState<T extends z.ZodTypeAny>(
  schema: SchemaWithOnlyDefaultAndOptional<T>,
): readonly [z.infer<T>, (newParams: Partial<z.infer<T>>) => void];

// Implementation
export function useHashState<T extends Array<string> | z.ZodTypeAny>(keysOrSchema: T): any {
  if (Array.isArray(keysOrSchema)) {
    return _useHashStateWithKeysArray(keysOrSchema);
  } else {
    return _useHashStateWithZodSchema(keysOrSchema);
  }
}

export function _useHashStateWithKeysArray<T extends string>(keys: Array<T>) {
  const [hashParams, setHashParams] = useState<HashParams<T>>(
    keys.reduce((acc, key) => ({ ...acc, [key]: [] }), {} as HashParams<T>),
  );

  const parseHash = useCallback((): HashParams<T> => {
    const urlHashes = LocationHelper.getDecodedHashParams();

    //@ts-expect-error It is safe to assume that the keys are strings
    const result: HashParams<T> = {};
    keys.forEach((key) => {
      const value = urlHashes[key];
      result[key] = value ? value.flatMap((s) => s.split(",")) : [];
    });
    return result;

    // use JSON representation of keys as dependency to avoid unnecessary re-renders
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [JSON.stringify(keys)]);

  const updateHash = useCallback(
    (newParams: Partial<HashParams<T>>) => {
      const urlHashes = LocationHelper.getDecodedHashParams();

      for (const hashKeys in newParams) {
        // If we pass `undefined` as a value, we should remove the key from the hash
        const newValue = newParams[hashKeys] ?? [];

        const noValuesForThisKey = newValue.length === 0;
        if (noValuesForThisKey) {
          delete urlHashes[hashKeys];
          continue;
        }

        urlHashes[hashKeys] = newValue;
      }
      LocationHelper.addHashToUrlWithoutReload(Object.entries(urlHashes).map(([key, value]) => ({ key, value })));
      setHashParams(parseHash());
    },
    [parseHash],
  );

  useEffect(() => {
    const doParse = () => {
      setHashParams(parseHash());
    };
    window.addEventListener("hashchange", doParse);
    doParse();

    return () => {
      window.removeEventListener("hashchange", doParse);
    };
  }, [parseHash]);

  return [hashParams, updateHash] as const;
}

export function _useHashStateWithZodSchema<T extends z.ZodTypeAny>(schema: T) {
  type State = z.infer<T>;
  const _schema = useMemo(() => schema.catch({}), [schema]); //Add a catch all to avoid runtime errors. At worst we will get an empty object

  const parseHash = useCallback((): State => {
    const decodedHashParam = decodeHashParamFromWindowLocation();
    const parsedHash = _schema.parse(decodedHashParam);
    return parsedHash;
  }, [_schema]);
  const [hashParams, setHashParams] = useState<State>(parseHash);

  const updateHash = useCallback(
    (newParams: Partial<State>) => {
      const newHashParam = { ...decodeHashParamFromWindowLocation() };

      for (const hashKeys in newParams) {
        const newValue = newParams[hashKeys] ?? undefined;

        // If we pass `undefined` as a value, we should remove the key from the hash
        const noValuesForThisKey = typeof newValue === "undefined" || newValue === undefined;
        if (noValuesForThisKey) {
          delete newHashParam[hashKeys];
          continue;
        }
        //else, update the value
        newHashParam[hashKeys] = newValue;
      }

      encodeHashParamAndUpdateWindowLocation(newHashParam);

      setHashParams(parseHash());
    },
    [parseHash],
  );

  useEffect(() => {
    const doParse = () => {
      setHashParams(parseHash());
    };
    window.addEventListener("hashchange", doParse);
    doParse();

    return () => {
      window.removeEventListener("hashchange", doParse);
    };
  }, [parseHash]);

  return [hashParams, updateHash] as const;
}
